using System;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class CandidatesPage:UserControl{DataGridView g=Ui.Grid();public CandidatesPage(){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52};if(AppSession.Can("Candidates.View")){var add=Ui.Button(L.T("add"));add.Click+=Add;bar.Controls.Add(add);}Controls.Add(g);Controls.Add(bar);LoadData();}void LoadData(){g.DataSource=Database.Query("SELECT Id,FullName AS [نام / Name],Mobile AS [موبایل / Mobile],Email,City AS [شهر / City],Education AS [تحصیلات / Education],PrimarySkill AS [مهارت / Skill],ExperienceYears AS [سابقه / Years],Status FROM Candidates ORDER BY Id DESC");}void Add(object s,EventArgs e){using(var f=new Form{Text=L.Fa?"کارجوی جدید":"New candidate",Width=500,Height=580,StartPosition=FormStartPosition.CenterParent}){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(25),WrapContents=false};var fields=new TextBox[6];string[] names=L.Fa?new[]{"نام کامل","موبایل","ایمیل","شهر","تحصیلات","مهارت اصلی"}:new[]{"Full name","Mobile","Email","City","Education","Primary skill"};for(int i=0;i<6;i++){p.Controls.Add(Ui.Label(names[i]));fields[i]=Ui.Text();fields[i].Width=400;p.Controls.Add(fields[i]);}var b=Ui.Button(L.T("save"));b.Click+=(a,z)=>{if(string.IsNullOrWhiteSpace(fields[0].Text))return;Database.Exec("INSERT Candidates(FullName,Mobile,Email,City,Education,PrimarySkill) VALUES(@a,@b,@c,@d,@e,@f)",new SqlParameter("@a",fields[0].Text),new SqlParameter("@b",fields[1].Text),new SqlParameter("@c",fields[2].Text),new SqlParameter("@d",fields[3].Text),new SqlParameter("@e",fields[4].Text),new SqlParameter("@f",fields[5].Text));Database.Audit("Create","Candidate",fields[0].Text);f.Close();LoadData();};p.Controls.Add(b);f.Controls.Add(p);Theme.Apply(f);f.ShowDialog(this);}}}}